const express = require('express');
const fs = require('fs');
const path = require('path');
const { pipeline, PassThrough } = require('stream');
const { StreamEntitlement } = require('../services/entitlements');

const app = express();

app.get('/stream/hls/:streamSessionId/segment.ts', async (req, res) => {
  const token = req.query.token || req.headers['x-playback-token'];
  if (!token) {
    return res.status(401).send('Playback token required');
  }

  // Verify entitlement for the specific stream session
  const isAuthorized = await StreamEntitlement.verifyPlayback(
    req.params.streamSessionId,
    token
  );

  if (!isAuthorized) {
    return res.status(403).send('Unauthorized stream access');
  }

  const segmentPath = path.join(
    '/var/streams/hls',
    req.params.streamSessionId,
    'live_chunk.ts'
  );

  if (!fs.existsSync(segmentPath)) {
    return res.status(404).end();
  }

  res.setHeader('Content-Type', 'video/mp2t');
  const readStream = fs.createReadStream(segmentPath);
  const passThrough = new PassThrough();

  pipeline(readStream, passThrough, res, (err) => {
    if (err && !res.headersSent) {
      res.status(500).end();
    }
  });
});

app.listen(3333);
